def _mime(b64: str) -> str:
    return "image/jpeg" if b64.startswith("/9j/") else "image/png"


def group_html(group: str, height: int = 92) -> str:
    cells = []
    for name, grp, b64 in EMBLEMS:
        if grp != group:
            continue
        cells.append(
            '<div style="width:130px;text-align:center;">'
            f'<img alt="{name}" title="{name}" src="data:{_mime(b64)};base64,{b64}" '
            f'style="height:{height}px;max-width:120px;width:auto;object-fit:contain;" />'
            f'<div style="font-size:12px;font-weight:600;line-height:1.2;margin-top:4px;">{name}</div></div>'
        )
    return '<div style="display:flex;flex-wrap:wrap;gap:14px;margin:6px 0 14px 0;">' + "".join(cells) + "</div>"


