def armed_forces_html(height: int = 130) -> str:
    cells = []
    for name, b64 in ARMED_FORCES:
        cells.append(
            '<div style="width:170px;text-align:center;">'
            f'<img alt="{name}" title="{name}" src="data:image/jpeg;base64,{b64}" '
            f'style="height:{height}px;max-width:160px;width:auto;object-fit:contain;" />'
            f'<div style="font-size:14px;font-weight:700;margin-top:4px;">{name}</div></div>'
        )
    return '<div style="display:flex;flex-wrap:wrap;gap:24px;margin:8px 0 14px 0;">' + "".join(cells) + "</div>"

