def flags_html(kind: str, height: int = 90) -> str:
    cells = []
    for name, grp, b64 in FLAGS_ROUNDELS:
        if grp != kind:
            continue
        mime = "image/jpeg" if b64.startswith("/9j/") else "image/png"
        cells.append(
            '<div style="width:170px;text-align:center;">'
            f'<img alt="{name}" title="{name}" src="data:{mime};base64,{b64}" '
            f'style="height:{height}px;max-width:160px;width:auto;object-fit:contain;border:1px solid rgba(128,128,128,.3);" />'
            f'<div style="font-size:13px;font-weight:600;margin-top:4px;">{name}</div></div>'
        )
    return '<div style="display:flex;flex-wrap:wrap;gap:20px;margin:6px 0 12px 0;">' + "".join(cells) + "</div>"
